python3 -I - <<'EOF'
import json
def load(p): return [json.loads(l) for l in open(p) if l.strip()]
old = {r["case_id"]: r for r in load("logs/historical/pass_a/cases.jsonl")}
new = {r["case_id"]: r for r in load("/tmp/mypass/cases.jsonl")}
for cid in old:
    o, n = old[cid], new[cid]
    diffs = []
    for k in ("accepted","exit_code","message"):
        if o[k] != n[k]: diffs.append(f"{k}: {o[k]!r} -> {n[k]!r}")
    if "run" in o or "run" in n:
        if json.dumps(o.get("run"),sort_keys=True) != json.dumps(n.get("run"),sort_keys=True):
            diffs.append("run record differs")
    print(cid, "SAME" if not diffs else diffs)
EOF

