arguments.command:
python3 -I - <<'EOF'
import json
from collections import Counter
reg = json.load(open("registry/missing_images.json"))
excl = {(i["source"], i["instance_id"]) for i in reg["selected"]}
for p in ("p_balanced","p_zero_weight","p_smith_only","p_legacy_manifest","p_small_mixed","p_60_30_10","p_no_total","p_float_total","p_short_file"):
    rows=[json.loads(l) for l in open(f"pools/{p}/queries.jsonl")]
    ids={(r["metadata"]["pool_source"],r["metadata"]["instance_id"]) for r in rows}
    print(p, "unusable present:", sorted(ids & excl))
EOF

